#if UNITY_EDITOR
using UnityEditor;using UnityEngine;namespace HabitatShift.LevelLabR10 { public static class R10GeneratorPanel { public static void Draw(ref R10GeneratorProfile p,System.Action<R10Candidate,string> action){EditorGUILayout.LabelField("GENERATOR",EditorStyles.boldLabel);p.archetype=(R10Archetype)EditorGUILayout.EnumPopup("Archetype",p.archetype);p.cols=EditorGUILayout.IntSlider("Cols",p.cols,5,10);p.rows=EditorGUILayout.IntSlider("Rows",p.rows,5,10);p.habitatCount=EditorGUILayout.IntSlider("Habitats",p.habitatCount,1,8);p.dualRingCount=EditorGUILayout.IntSlider("Dual Ring",p.dualRingCount,0,p.habitatCount);p.elevatorCount=EditorGUILayout.IntSlider("Elevators",p.elevatorCount,0,3);p.obstacleCount=EditorGUILayout.IntSlider("Obstacles",p.obstacleCount,0,6);p.dependencyDepth=EditorGUILayout.IntSlider("Dependency depth",p.dependencyDepth,0,p.habitatCount);p.seed=EditorGUILayout.IntField("Seed",p.seed);p.candidateCount=EditorGUILayout.IntSlider("Candidate count",p.candidateCount,1,12);p.beamWidth=EditorGUILayout.IntField("Beam width",p.beamWidth);p.nodeLimit=EditorGUILayout.IntField("Node limit",p.nodeLimit);p.scrambleDepth=EditorGUILayout.IntSlider("Scramble depth",p.scrambleDepth,0,8);if(GUILayout.Button("GENERATE "+p.candidateCount)){R10CandidateBrowser.Candidates.Clear();R10CandidateBrowser.Candidates.AddRange(R10Generator.Batch(p));}EditorGUILayout.LabelField("CANDIDATES",EditorStyles.boldLabel);foreach(var c in R10CandidateBrowser.Candidates.ToArray()){EditorGUILayout.BeginHorizontal("box");EditorGUILayout.LabelField(c.id,GUILayout.Width(100));EditorGUILayout.LabelField(c.status,GUILayout.Width(95));EditorGUILayout.LabelField(c.solverStatus,GUILayout.Width(85));EditorGUILayout.LabelField("D "+c.density.ToString("P0"),GUILayout.Width(48));if(GUILayout.Button("EDIT",GUILayout.Width(42)))action(c,"EDIT");if(GUILayout.Button("PLAY",GUILayout.Width(42)))action(c,"PLAY");if(GUILayout.Button("PREVIEW",GUILayout.Width(58)))action(c,"PREVIEW");if(GUILayout.Button("DELETE",GUILayout.Width(54)))action(c,"DELETE");EditorGUILayout.EndHorizontal();}} }
}
#endif